class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._members_set = set(members)
        # Store balances in integer cents to avoid floating-point inaccuracies
        self._balances: dict[str, int] = {member: 0 for member in self.members}

    def add_expense(
        self, payer: str, amount: float, participants: list[str] | None = None
    ) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be strictly positive.")

        if payer not in self._members_set:
            raise ValueError(f"Payer '{payer}' is not a group member.")

        if participants is None:
            participants = list(self.members)
        elif not participants:
            raise ValueError("Participants list cannot be empty.")
        else:
            for p in participants:
                if p not in self._members_set:
                    raise ValueError(f"Participant '{p}' is not a group member.")

        total_cents = round(amount * 100)
        share_per_person = total_cents // len(participants)

        # Every other participant owes `share_per_person`.
        # Leftover cents are naturally borne by the payer because the payer
        # is only reimbursed `share_per_person` by each other participant.
        for p in participants:
            if p != payer:
                self._balances[p] -= share_per_person
                self._balances[payer] += share_per_person

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money,
        negative = the member owes money."""
        return {member: self._balances[member] / 100.0 for member in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        # Debts below 1.00 (100 cents) are written off
        debtors = [
            [member, -self._balances[member]]
            for member in self.members
            if self._balances[member] <= -100
        ]
        creditors = [
            [member, self._balances[member]]
            for member in self.members
            if self._balances[member] >= 100
        ]

        payments: list[tuple[str, str, float]] = []
        i = 0
        j = 0

        while i < len(debtors) and j < len(creditors):
            debtor_name, debt_cents = debtors[i]
            creditor_name, credit_cents = creditors[j]

            pay_cents = min(debt_cents, credit_cents)

            if pay_cents >= 100:
                payments.append((debtor_name, creditor_name, pay_cents / 100.0))
                debtors[i][1] -= pay_cents
                creditors[j][1] -= pay_cents

            # If remaining debt or credit is under 1.00, write it off and advance
            if debtors[i][1] < 100:
                i += 1
            if creditors[j][1] < 100:
                j += 1

        return payments
```

